::v-deep .el-card{
  overflow: initial;
}

.menus{
  position: fixed;
  top: 32%;
  right: 13px;
  .menus_item{
    width: 40px;
    height: 130px;
    background: url(require('@/assets/safeDanger/menu2.png')) no-repeat;
    background-size: 100%;
    font-size: 18px;
    color: #fff;
    cursor: pointer;
    text-align: center;
    padding-top: 22px;

    span{
      display: inline-block;
      width: 20px;
    }
  }
  .menus_item-a{
    background: url(require('@/assets/safeDanger/menu1.png')) no-repeat;
    background-size: 100%;
  }
}


::v-deep .el-card__header{
  border-bottom: 0;
}
.title_wrap{
  width: 100%;
  height: 34px;
  background: url(require('@/assets/safeDanger/headBg.png')) no-repeat;
  background-size: 100%;
  position: relative;
  padding-left: 25px;
  line-height: 30px;
  font-size: 16px;
  color: #333;

  .img1{
    width: 6.5px;
    position: absolute;
    left: 10px;
    top: 9px;
  }
  .img2{
    position: absolute;
    top: 22px;
    right: 5px;
    width: 23px;
  }
}


.title_card{
  display: flex;
  flex-direction: column;
  justify-content: space-around;
  align-items: center;
  padding: 10px 0px;
  color:#606266;
  font-weight: bold;
  font-size: 14px
}
.index >>> .el-card__header{
  font-size: 15px;
  color: #606266;
  font-weight: bold
}
.card0{
  background: linear-gradient(to right, #ffc75e, #ff5f37)
}
.card1{
  background: linear-gradient(to right, #8ddfff, #7fabfd)
}
.card2{
  background: linear-gradient(to right, #f49ae7, #b470fe)
}
.card3{
  background: linear-gradient(to right, #7ae9e7, #47e6c3)
}
.card4{
  background: linear-gradient(to right, #b0c1e1, #647799)
}
.card5{
  background: linear-gradient(to right, #ffbbdb, #ff6caa);

}
